+    const strings = english ? en.eventTask : es.eventTask;
+    const text = strings[key.replace('eventTask.', '') as keyof typeof strings] ?? key;
+    return text.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(options[name] ?? ''));
